#include <iostream>
#include <vector>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, m;
    std::cin >> n >> m;

    std::vector<int> degree(n, 0);
    for (int i = 0; i < m; ++i) {
        int u, v;
        std::cin >> u >> v;
        --u; --v;
        ++degree[u];
        ++degree[v];                    // both endpoints, even when they coincide
    }

    for (int i = 0; i < n; ++i) std::cout << degree[i] << " \n"[i == n - 1];
}
